INSERT INTO changelog (title, body, created_at) VALUES ('Інтерактивні таблиці', 'Таблиці стали «живими»: Meta → Кампанії і По місяцях, Продажі → Реклама → продажі, Креативи клієнта → «Усі оголошення» (нова плитка: усі оголошення за весь час з кодом креативу, ціною ліда і % до середньої), Центр креативів → Формати, Гроші → Хто скільки платить.
Що вміють: клік по заголовку — сортування (↑ → ↓ → як було); тягни за ⠿ — переставити колонку; тягни правий край заголовка — ширина (подвійний клік — як було); «Колонки» — сховати/показати, 📌 закріпити зліва, ↑↓ без мишки, «Скинути вигляд»; Щільно / Звичайно / Просторо; пошук, коли рядків більше 8. Вигляд кожної таблиці запамʼятовується в браузері (на іншому пристрої — свій).', datetime('now'));
